"Pod inbound! Reinforcements!":"Pod tiba! Bantuan datang!",
"Anyone remember why the sky is a portal?":"Ada sesiapa ingat kenapa langit itu portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Katanya kalau terjun dalam syaf, kita muncul di syaf musuh. Tak nak cuba.",
"The Swarm painted their visors red again. Show-offs.":"Swarm mengecat visor mereka merah lagi. Suka menunjuk.",
"Ore, ore… when do we get some oil?":"Ore, ore… bila kita dapat minyak?",
"I dreamt I was a toaster. It was peaceful.":"Saya mimpi saya sebuah pembakar roti. Tenang saja.",
"Quiet. Too quiet.":"Senyap. Terlalu senyap.",
"See that? Our base is above the Swarm base again. Portals, man.":"Nampak tak? Pangkalan kita di atas pangkalan Swarm lagi. Itulah portal.",
"Diman, if you're reading this — we need a vacation.":"Diman, kalau kau baca ini — kami perlukan cuti.",
