"Browser storage is full":"Storan pelayar penuh",
"Battle loaded: {0}":"Pertempuran dimuatkan: {0}",
"Autosaved":"Disimpan secara auto",
"robot war · the sky is a portal":"perang robot · langit ialah portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Selamat datang ke meteor! Anda ialah robot tempur Consortium. Lihat sekeliling dengan tetikus dan berjalan dengan WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: ketik Shift untuk melompat, tahan Shift untuk terbang. Tenaga dicas semula di tanah.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Tembak — klik kiri. Bidik — klik kanan: lebih tepat, dengan zum. Lepaskan beberapa tembakan.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Isi semula — R. Peluru paling kuat pada jarak sederhana, 20–50 meter.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Roket — Q. Untuk kereta kebal dan bangunan. Lepaskan roket.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Di atas ialah arahan ahli strategi. Berlari ikut anak panah hijau: anda memecut di laluan. Rampas titik — berdiri dekat suar.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Skuad anda melindungi anda: potret dan kesihatan mereka di sebelah kiri. Jika ketinggalan, mereka akan minta anda menunggu.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — tukar unit pantas tanpa keluar dari pertempuran: lompat ke skuad atau kereta kebal paling dekat dengan pertempuran. Cubalah.",
"Next to a tank or turret press E to take control. Or just carry on.":"Di sebelah kereta kebal atau menara meriam, tekan E untuk mengawalnya. Atau teruskan sahaja.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Sekarang strategi. Ketik \"◩ Strategi\" di kanan atas — pandangan atas medan perang.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Sekarang strategi. Tekan {0} (atau \"◩ Strategi\" di kiri atas) — pandangan atas medan perang.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Dalam strategi, Curator membantu kamu: kotak di atas memberitahu apa yang perlu dibuat, bingkai menunjukkan butang, gelang menandakan tempat di peta. Selesaikan tiga nasihatnya.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Pilih skuad dan ketik butang hijau \"▶ Possess\" — kembali ke pertempuran sebagai askar itu. Semasa kamu menembak, ahli strategi AI mengendalikan tentera.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Pilih skuad dan tekan {0} atau \"▶ Possess\" yang hijau — kembali ke pertempuran sebagai askar itu (tiada pilihan — askar kamu sendiri). Semasa kamu menembak, ahli strategi AI mengendalikan tentera.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Latihan tamat! Swarm melancarkan serangan. Semoga berjaya, askar!",
"TRAINING":"LATIHAN",
"skippable in":"boleh dilangkau dalam",
