"New in v6.3":"Baharu dalam v6.3",
"New in v6.2":"Baharu dalam v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Rupa bijih baharu: urat ialah kristal zamrud berfacet bercahaya di atas basalt hitam dengan percikan api dan kabus hijau; pengekstrak ialah alas heksagon dengan kubah sarang lebah dan menara kekisi bersama suar hijau di atas (jalur dan panji warna pasukan)",
"New in v6.1":"Baharu dalam v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Kelas pilihan seperti dalam Battlefield (U, nombor selepas mati): anda muncul semula dalam kelas itu apabila ada",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Kenderaan dari sudut pandang pertama (V — luar/kokpit); bantuan bidik ringan — dalam Tetapan",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Keluar dari teras kini mudah: Space — ke aci, B — kapsul ke permukaan; kesan kebolehan ditetapkan semula apabila mati",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Kemajuan tanpa had: jeneral dan Marshal ★, tahap kerjaya, penguasaan senjata dan aksesori, pingat, kontrak harian — skrin Kerjaya",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategi: zum roda tetikus yang lancar, ikon dan label unit (Alt — semua), panel Tentera / Bangunan di sebelah kiri",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"klik kanan — gerak serang, klik kanan dua kali — mara sambil menembak; arahan jarang di \"Lagi arahan ▾\"; tiada butang berganda",
"New in v6":"Baharu dalam v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Senjata ala penembak: peluru hitscan, senapang 720 RPM, MG, rejang, bidik klik kanan, magazin dan isi semula R, penanda tembakan kena",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Graviti lebih berat, jetpack responsif, terjahan dengan Z atau jetpack dua kali di udara; senjata tidak lagi ikut terbang ketika menukar unit",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Jurutera: pilih jurutera, pilih bangunan, letak pelan; Pengekstrak di urat bijih; klik \"BIJIH\" untuk lihat pendapatan dan cara meningkatkannya",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Butang kelabu menerangkan sebabnya dan menawarkan penyelesaian; butang lebih besar, jalur \"Sedang berjalan\", \"▶ Kawal\", Tab ialah satu-satunya kekunci mod",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera strategi tanpa lonjakan atau terbalik, zum ke kursor, peta mini boleh diseret",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Kenderaan baharu: perompak \"Jackal\", MLRS \"Grad\" (roket pencari sasaran), mortar \"Hammer\"; Kawanan mendapat \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strategis tidak mengubah arahan dan berhenti spam suara; pertempuran datang kepada anda; B — pindah, Shift+B — ke tengah pertempuran; kompas, H — sasaran mana",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Bermain bebas (K) dan bertindak solo (J), pratetap F2; Esc jeda dan sambung; simpanan: slot, eksport dan import",
"New in v5.3":"Baharu dalam v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Penerbangan: graviti lebih kuat jauh dari meteor, C di udara memberi brek, tujahan mengemudi lebih tajam; tidak lagi tersangkut dalam portal",
"New in v5":"Baharu dalam v5",
"Endless war by default and battle scale: normal, large, epic":"Perang tanpa penghujung secara lalai dan skala pertempuran: biasa, besar, epik",
"Save and load the battle (autosave every 3 minutes)":"Simpan dan muat pertempuran (simpan automatik setiap 3 minit)",
"Squadmates with callsigns: portraits, health and live chatter":"Rakan skuad dengan tanda panggilan: potret, kesihatan dan perbualan hidup",
"Fog of war in strategy, friends and foes outlined differently":"Kabus perang dalam strategi, kawan dan lawan diserlahkan secara berbeza",
"Camera fly-over when switching, portal aurora instead of rings":"Terbang kamera semasa bertukar, aurora portal menggantikan gelang",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Tugasan sampingan, jalan pintas langit, habitat ekspedisi pertama dengan bekalan, kristal, ais kawah, ribut debu",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Latihan, mod sinema dengan rakaman video, kenderaan pengiring daripada ahli strategi",
