"Curator":"Kurator",
"Guides you during play: arrows to buttons and marks on the map. Turn it off any time (also in Settings).":"Membimbing anda semasa bermain: anak panah ke butang dan tanda di peta. Matikan bila-bila masa (juga dalam Tetapan).",
"queue {0}/5":"baris gilir {0}/5",
"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"Pilih HQ dan latih jurubina (50 bijih) — klik untuk membuka panel HQ",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"Jurubina dilatih hanya di HQ: pilih HQ (klik atau F2) — panel pengeluarannya terbuka di sebelah kanan. Begitu juga kilang mech, pusat dron, dok udara dan pos hadapan",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"Tab Bina dibuka apabila jurubina dipilih; butang \"Pilih jurubina terdekat\"; Z X C V B N K memilih jurubina secara automatik",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"Kurator menggantikan tutorial strategi: mencadangkan apa yang perlu dibuat semasa bermain, menunjuk butang dan menanda peta; matikan di panel atau dalam Tetapan",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"Mod pembangun (menu utama): bijih tanpa had, semua dibuka, bina serta-merta, Arsenal — sebarang senjata, kelas, kenderaan, sasaran latihan; kerjaya anda tidak terjejas",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"Telefon: butang Penembak tidak lagi menutup silang bidik atau senjata, panel strategi boleh dikuncupkan, butang lebih besar, suis \"Strategi ⇄ Pertempuran\" yang jelas",
"Combined build: the v6.2 ore-vein crystals and extractors + grenades with a throw arc":"Binaan gabungan: kristal urat bijih dan pengekstrak v6.2 + bom tangan dengan lengkung lontaran",
"New in v6.4":"Baharu dalam v6.4",
"Curator on: I will suggest what to do":"Kurator dihidupkan: saya akan mencadangkan apa yang perlu dibuat",
