"BUILDER":"JURUTERA",
"VEIN ⛏":"URAT ⛏",
"ENEMY":"MUSUH",
"Select a builder: the \"⚒ Select nearest builder\" or \"⚒ Builder\" button.":"Pilih jurutera: butang \"⚒ Pilih jurutera terdekat\" atau \"⚒ Jurutera\".",
"Select a builder: \"⚒ Select nearest builder\" on the right or click one.":"Pilih jurutera: \"⚒ Pilih jurutera terdekat\" di kanan atau klik pada jurutera.",
"Tap the marked vein ⛏ (glowing crystals), then \"✔ Build\". Mark off-screen — tap it to fly the camera there.":"Ketik urat bertanda ⛏ (kristal bercahaya), kemudian \"✔ Bina\". Tanda di luar skrin — ketik untuk terbangkan kamera ke sana.",
"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"Klik urat bertanda ⛏ — kristal bercahaya (klik kanan/Esc — batal). Tanda di luar skrin — klik untuk terbangkan kamera ke sana.",
"Tap a spot for the {0}, then \"✔ Build\".":"Ketik tempat untuk {0}, kemudian \"✔ Bina\".",
"Click a spot for the {0} (RMB/Esc — cancel).":"Klik tempat untuk {0} (klik kanan/Esc — batal).",
"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"Saya Kurator: saya serlahkan butang dan tempat di peta. \"✕\" mematikan saya.",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"Saya Kurator. Saya akan mencadangkan apa yang perlu dibuat semasa bermain, dengan menyerlahkan butang dan tempat di peta. Matikan saya dengan \"✕\" di sini atau butang \"Kurator\" di bawah kanan.",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"Kawanan di pangkalan! \"Seluruh tentera\", kemudian ketik lama pada musuh. Menara meriam di pangkalan juga membantu.",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"Kawanan di pangkalan! Pilih pasukan (kotak atau Ctrl+A) dan klik kanan pada musuh. Menara meriam (Z) juga membantu.",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"Kamera: seret peta dengan jari, dua jari — zum dan putar. Gerakkan kamera.",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"Kamera: WASD atau tepi skrin, roda — ketinggian, Q/E — putar. Gerakkan kamera.",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"Tiada jurutera — dan tiada apa dapat dibina tanpa mereka. Pilih Ibu Pejabat — klik padanya atau butang \"⌂ Ibu Pejabat\".",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"Tempah jurutera — butang \"⚒ Jurutera\" dalam panel Ibu Pejabat (50 bijih).",
"We need ore — let us put an extractor on an ore vein.":"Kita perlukan bijih — mari pasang pengekstrak pada urat bijih.",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"Tekan \"Pengekstrak\" (C) dan letakkan pada kristal bercahaya di urat — saya telah menandanya ⛏.",
"Few troops. Select the HQ — squads are ordered there.":"Pasukan sedikit. Pilih Ibu Pejabat — skuad ditempah di situ.",
"Order an \"Assault squad\" in the HQ panel.":"Tempah \"Skuad serbuan\" dalam panel Ibu Pejabat.",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"Titik memberi bijih. Pilih skuad — ketik padanya atau butang \"◈ Skuad\" di kanan.",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"Titik memberi bijih. Pilih skuad — ketik padanya atau kad \"◆ Tentera\" di atas.",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"Titik memberi bijih. Pilih skuad — klik padanya atau kadnya dalam panel \"◆ Tentera\" di kiri.",
"Long-tap point {0} — the squad goes to capture it.":"Ketik lama pada titik {0} — skuad akan pergi merampasnya.",
"RMB on point {0} — the squad goes to capture it.":"Klik kanan pada titik {0} — skuad akan pergi merampasnya.",
"POINT ":"TITIK ",
"The base is under attack — let us build a turret.":"Pangkalan diserang — mari bina menara meriam.",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"Tekan \"Menara meriam\" (Z) dan letakkan di pangkalan, menghadap musuh.",
"Enough ore for a mech factory — it makes tanks and vehicles.":"Bijih cukup untuk kilang mech — ia membuat kereta kebal dan kenderaan.",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"Tekan \"Kilang mech\" (B) dan letakkan di pangkalan (tempat rata dalam cincin putus-putus).",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0} menganggur — pilih dan beri arahan: {1} titik atau musuh.",
"The mech factory is ready. Select it to order a tank.":"Kilang mech siap. Pilihnya untuk menempah kereta kebal.",
"Order a \"Tank\" in the factory panel.":"Tempah \"Kereta kebal\" dalam panel kilang.",
"More extractors — more ore. There is a free vein nearby.":"Lebih banyak pengekstrak — lebih banyak bijih. Ada urat kosong berdekatan.",
"\"Extractor\" (C) on the marked vein ⛏.":"\"Pengekstrak\" (C) pada urat bertanda ⛏.",
"Pick a power and click an enemy cluster.":"Pilih kuasa dan klik pada kumpulan musuh.",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"Mata arahan terkumpul — tab \"✺ Kuasa\": serangan artileri, peninjauan, pod pendaratan.",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"Bijih kurang? Ketik \"BIJIH\" di atas — lihat dari mana pendapatan datang dan cara meningkatkannya.",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"Mahu bertarung sendiri? Pilih skuad dan tekan \"▶ Kawal\".",
