"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Model mengikut normal permukaan meteor, memusingkan batang tubuh untuk membidik dan memegang mesingan; dari jauh animasi dikemas kini kurang kerap untuk mengekalkan FPS",
