"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Kamu boleh bina pangkalan, arah pasukan, memerintah dan melompat ke pertempuran. Seterusnya — perlawanan sebenar: Pembimbing akan membantu semasa bermain.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Kamu boleh bergerak, terbang, menembak, berlindung dan memerintah skuad. Seterusnya — perlawanan sebenar.",
