"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Kotak pasir selamat: musuh masih orang-orangan, tiada yang menembak kamu. Langkah dikira hanya apabila kamu benar-benar melakukan tindakan itu.",
