"Old training (v7.1)":"Latihan lama (v7.1)",
"Back to the normal device mode":"Kembali ke mod peranti biasa",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Latihan untuk peranti lain akan memuat semula halaman dalam modnya (PC — tetikus dan papan kekunci, telefon — sentuhan; pada PC kamu boleh menguji sentuhan dalam Chrome: F12 → ikon telefon).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Latihan ×4: pelajaran langkah demi langkah \"Strategi\" dan \"Penembak\" yang berasingan untuk PC dan telefon. Kotak pasir selamat dengan orang-orangan, butang yang betul diserlahkan, anak panah, kekunci, tetikus dan gerak isyarat beranimasi; langkah dikira hanya untuk tindakan sebenar, \"ulang langkah\", kemajuan di atas dan ganjaran di penghujung",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Menu Latihan menunjukkan pelajaran untuk peranti kamu; \"Tunjuk yang lain\" — keempat-empatnya pada mana-mana peranti; \"Latihan lama (v7.1)\" masih ada",
"New in v7.2":"Baharu dalam v7.2",
"NEW IN v7.2":"BAHARU DALAM v7.2",
"No grenades left":"Bom tangan sudah habis",
"Rocket and grenade recharging · {0} s":"Roket dan bom tangan sedang dicas semula · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Kiri — bergerak, kanan — melihat · ketik musuh — roket / bom tangan · 2 ketikan — refleks · 3 ketikan — serangan artileri",
"Less":"Kurang",
"More":"Lagi",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Ada kenderaan atau binaan musuh berdekatan — ketik padanya: roket dilancarkan.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Ramai musuh — ketik dua kali pada tempat kosong di kanan: refleks memperlahankan masa.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Halakan bidikan pada kumpulan musuh dan ketik 3 kali — serangan artileri.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Ibu jari kiri — bergerak, ibu jari kanan — melihat. Menembak sendiri apabila dibidik pada musuh.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ di tepi kiri — jetpack: ketik untuk melompat, tahan untuk terbang.",
"Old v7.2 layout":"Susun atur lama v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Seret jari pada separuh kanan skrin — kayu bedik pandangan muncul di bawah jari.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Sentuh sebelah kiri dan gelongsor — kayu bedik muncul di bawah jari anda. Capai penanda hijau.",
"Hold the \"Jet\" button at the left edge.":"Tahan butang \"Jet\" di tepi kiri.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Bidik patung sasaran dengan kayu bedik kanan — askar anda menembak sendiri apabila pemidang berada padanya.",
"Tap the dummy on the screen — a rocket flies.":"Ketik patung sasaran pada skrin — roket dilancarkan.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Ketik patung sasaran — bom tangan terbang melengkung, tepat ke arahnya.",
"Double tap an empty spot on the right quickly.":"Ketik dua kali dengan pantas pada tempat kosong di kanan.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Mod ringan untuk telefon lemah: resolusi lebih rendah, tiada bayang atau herotan, separuh bot dan zarah, had 30 FPS; menurunkan resolusi sendiri jika FPS < 25. Dihidupkan secara lalai pada telefon (Tetapan → Grafik → \"Mod ringan\"; atau ?lite=1 / ?lite=0 dalam pautan).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: kawalan baharu. Kiri — bergerak, kanan — melihat (kedua-dua kayu bedik muncul di bawah jari anda). Ibu jari kiri sahaja — \"auto\"; apabila yang kanan digunakan, askar menembak sendiri hanya semasa pemidang berada pada musuh. Ketik musuh — roket atau bom tangan, 2 ketikan — refleks, 3 ketikan — serangan artileri. Isi semula automatik. Jetpack — butang di tepi kiri. Bucu bawah kosong, minipeta di bucu, petunjuk boleh ditutup dengan silang, objektif boleh dilipat. Susun atur lama: Tetapan → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Petunjuk (pop timbul dan Kurator) — satu suis dalam tetapan. Anda bermain sebagai siapa (jenis askar atau kenderaan) — label \"Anda: …\" dalam HUD. Optik senapang dan mesingan lut sinar. Panel \"Senjata\" dilabuhkan di kanan, boleh dilipat dan dimatikan. \"Solo tanpa skuad\" (J) dibuang. Suara AI strategist tidak lagi mengulang baris yang sama. Kereta kebal mendapat penunjuk menara berbanding badan. Kursor tidak lagi hilang pada permulaan latihan strategi.",
