"Voice of hints & curator":"Suara petunjuk & Kurator",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: tiga mod kayu bedik. Kiri sahaja — \"auto\" (magnet kuat, peluru lebih lemah). Kanan sahaja — bidikan hidup sendiri, magnet lebih kuat, ketepatan lebih baik. Kedua-duanya — tiada bidikan, magnet dan ketepatan lebih lemah. Butang 👁 di kanan menyembunyikan/memulangkan HUD.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategi dipermudah — jurutera dan bangunan sahaja. Kad di kiri (jurutera, HQ, berek…): ketik — kamera terbang ke sana, bar bawah menunjukkan apa yang hendak dibina/dihasilkan. \"Ke medan\" — kiri atas. Tentera bertempur sendiri. Strategi penuh — Tetapan → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Kawal — dua suis: \"Skuad\" dan \"Kenderaan\" (kenderaan dimatikan secara lalai pada telefon — AI yang memandunya). Dengan kenderaan dimatikan, E (telefon: butang di kanan) di sebelah kenderaan sekutu — kendalikan meriamnya: ia bergerak sendiri, anda menembak. Susunan kelas tersuai lama ada di bawah \"Lanjutan\". Unit menjawab melalui radio apabila anda mengawalnya.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Petunjuk pintar: petunjuk asas padam sendiri selepas pelancaran ke-2, tetapi permainan tetap menunjukkan ciri yang tidak pernah anda guna. Suis: asas / lanjutan / jarang, dan satu lagi untuk suara petunjuk dan Kurator.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks dicas daripada pembunuhan (siri membunuh mengecas lebih). Rakan skuad ketinggalan atau mati — AI strategist menurunkan yang baharu ke arah anda (lebih mahal daripada bantuan biasa). Grafik dan bunyi v7.2gfx telah digabungkan: letupan berkepul, asap, serpihan, akustik syaf dan kawah. Tarikh binaan kini sebenar.",
