"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Kerjaya dan simpanan tidak berubah. Dalam pertempuran, menu yang sama ialah butang \"🛠 Menu\" di kanan atas{0}.",
"New developer match":"Perlawanan pembangun baru",
"all unlocked, endless ore, instant build, arsenal":"semua dibuka, bijih tanpa had, binaan segera, senjata",
"Trainings — all 4":"Latihan — semua 4",
