"Cinema: everything built":"Pawagam: semua dibina",
"both bases built and upgraded — for footage":"kedua-dua pangkalan dibina dan dinaik taraf — untuk rakaman",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mod pawagam — skrin pisah: bot ahli strategi di kiri (pandangan atas pangkalan dan tentera), bot penembak di kanan dari sudut pandangan orang pertama. Butang di bawah (kekunci S, P): \"Skrin pisah\" dan \"★ Semua dibina\" — kedua-dua pangkalan dibina dan dinaik taraf untuk rakaman.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Teras dan terowong menembusi meteor sudah tiada — meteor itu pejal, pertempuran hanya di permukaan.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 menyembunyikan HUD tetapi mengekalkan jetpack, ⇆, kayu bedik dan penanda objektif. \"◎ Bidik\" (jari kanan sahaja) — magnet yang jelas lebih kuat dan lebih luas; magnet untuk ketiga-tiga mod — Tetapan → Kawalan → \"Lanjutan\". Pada senjata kenderaan, butang itu tertulis \"Turun\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Latihan: telefon hanya memaparkan latihan telefon, PC hanya PC. Kesemua 4 ada dalam menu \"🛠 Pembangun\". Mod pembangun dan Arsenal kini satu menu (dalam pertempuran — \"🛠 Menu\" di kanan atas, F8 pada PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Gaya grafik \"Dendy (8-bit)\" dan \"16-bit\": Tetapan → Grafik → \"Gaya grafik\" (butiran — butang ⚙). Jika FPS di bawah 24 dalam ~10 s pertama perlawanan, Dendy hidup sendiri (jika masih di bawah 20 — piksel lebih besar, 120 baris); notis \"kembali normal\" memulihkan grafik biasa untuk selamanya. Pilihan anda sendiri dalam menu sentiasa diutamakan.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Model persekitaran 3D (runtuhan, bangkai, kubu) — hanya yang dinilai baik, dimuat mengikut permintaan. Matikan: Tetapan → Grafik → \"Model persekitaran 3D baharu\".",
