"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Askar boleh membina: E (telefon: \"Masuk\") di tapak binaan sendiri — askar anda membina, rakan skuad berdekatan membantu. Jika jurutera sibuk, ahli strategi meminta bantuan anda — penanda \"TAPAK BINAAN\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Tanda ahli strategi: ahli strategi meletakkan ⌖ pada kumpulan musuh berhampiran anda — artileri menghentamnya 8 s kemudian dan MLRS \"Grad\" sekutu berdekatan melepaskan tembakan serentak. Serangan artileri anda sendiri dari mod strategi turut mendapat sokongan \"Grad\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Simpanan senjata dalam kontena kargo dan satelit terhempas (📦 kelihatan dalam 70 m): E — mesingan berat selama 90 s, peluru api atau roket, serta bom tangan penuh. Merangkak: Ctrl — tiarap / bangun (lebih rendah, sasaran lebih stabil, tetapi perlahan).",
"Anonymous statistics":"Statistik tanpa nama",
