"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"Tidak suka versi baharu — mainkan yang biasa anda guna. Pilihan diingati; setiap versi mempunyai simpanan dan tetapan sendiri (ini selamat). Versi lama dimuat hanya apabila dipilih.",
