"Link copied":"Pautan disalin",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Main sekarang\" — butang pertama menu: penerbangan singkat di bawah langit portal dan terus ke pertempuran (langkau dengan sebarang kekunci atau ketikan).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Tembakan terasa nyata: bunyi logam dan percikan api, penanda pembunuhan di anak panah (tembakan kepala — kuning), siri ×N, gegaran lembut daripada letupan, gerak perlahan pada pembunuhan utama. Gegaran, gerak perlahan dan petunjuk boleh dimatikan dalam Tetapan.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Keputusan perlawanan: masa, pembunuhan, siri terbaik, ★ MVP dan skuad terbaik, kad perlawanan — \"⇪ Kongsi\", PNG atau pautan ke permainan.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Petunjuk \"apa nak buat sekarang\" di sebelah kiri bawah sumber: arahan ahli strategi, titik untuk dirampas, serangan Kawanan. ✕ atau F7 — kecilkan.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Pertempuran disimpan sendiri apabila anda menutup atau menyembunyikan tab — \"⟲ Teruskan\" dalam menu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 kekal dalam menu \"🕘 Versi permainan\" sekiranya anda lebih suka. Statistik tanpa nama (tiada nama atau e-mel) kini dihantar; matikan dalam Tetapan.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Main sekarang\", maklum balas tembakan, keputusan perlawanan dengan kad kongsi, petunjuk \"apa nak buat\", simpanan automatik",
"and older: v7.5, v7.4, milestones v1–v7.0":"dan yang lama: v7.5, v7.4, pencapaian v1–v7.0",
"New in v7.6":"Baharu dalam v7.6",
"NEW IN v7.6":"BAHARU DALAM v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Pilih puak anda sebelum perlawanan: \"Konsortium\" (infantri berat berperisai kuasa, perisai dan artileri) atau \"Gala\" (kelajuan, pek dron, tembakan berat dengan herotan). AI memainkan yang satu lagi. Pilihan diingati.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Setiap puak mempunyai kenderaan dan keunikan sendiri: Konsortium — kereta kebal \"Rinoceronte\" dan \"Plat seramit\", Gala — \"Pek dron\" dan \"Jetpack fasa\". Keseimbangan disemak dengan perlawanan bot.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Kawah letupan: artileri, roket dan meriam kereta kebal menggali lubang pada meteor — kamu boleh berjalan dan memandu melaluinya, dan berlindung di dalamnya.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pandangan orang ketiga untuk askar (V, diingati; pada telefon — Kawalan) dan kamera kenderaan yang lancar dengan penanda tempat meriam akan mengena.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 kekal dalam menu \"🕘 Versi permainan\" sekiranya kamu lebih suka versi itu.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Puak Konsortium / Gala dengan pilihan sebelum perlawanan, kawah letupan, pandangan orang ketiga",
