"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Menjatuhkan peti berhampiran pasukan kamu: peluru, bom tangan, roket, alat ganti senjata, kit pembaikan.",
"\"Grad\" rocket strike":"Serangan roket \"Grad\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 roket ke kawasan luas selepas 3 saat — lebih pantas dan lebih luas daripada serangan artileri.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Sokongan: peti, peninjauan, \"Grad\", serangan artileri (kemudian 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"AMARAN: \"Grad\" Gala menuju kawasan kamu!",
"Warning! Rocket salvo on our position!":"Awas! Tembakan roket serentak ke atas posisi kita!",
"take the supply crate":"ambil peti bekalan",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomali di meteor (gelombang 1): \"Veta Cantora\" — kristal hijau bercahaya yang berdengung dan menyerang semua yang berdekatan dengan denyutan berirama; \"Pusaran\" menarik dan menghempas, \"Pemetir\" melepaskan kilat antara batang, \"Kuali Api\" menyala di bawah kaki, \"Kabus asid\" dan \"Kanta\" (membengkokkan peluru dan pandangan kamu) berkeliaran.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomali boleh dirasai lebih awal (dengung, cahaya, bahang berbalam). Lepaskannya dengan bom tangan, roket atau bolt (E berhampirannya): ia akan tidur dan kadangkala meninggalkan artifak dengan kelebihan dan kekurangan. Skuad kamu memberi amaran melalui radio, dan musuh (juga kawan) kadangkala tersesat masuk — pancing mereka!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Sokongan dengan mata perintah (MP): 4 dalam pertempuran (📡 pada telefon) — kiriman bekalan, imbasan peninjauan, serangan roket \"Grad\", serangan artileri pada garis bidik. Ahli strategi hanya nampak anomali pada peta selepas imbasan.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Peti bekalan dalam runtuhan ekspedisi lama, berhampiran QG dan di sebelah bangunan siap: peluru, bom tangan, roket, alat ganti senjata (membuka kunci aksesori).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 kekal dalam menu \"🕘 Versi permainan\". Anomali boleh dimatikan dalam Tetapan.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomali (\"Veta Cantora\" dan 5 lagi), pelepasan dengan bolt atau bom tangan, artifak, panggilan sokongan dengan MP, peti bekalan",
"and older: v7.7, v7.6, milestones v1–v7.0":"dan yang lebih lama: v7.7, v7.6, pencapaian v1–v7.0",
"New in v7.8":"Baharu dalam v7.8",
"NEW IN v7.8":"BAHARU DALAM v7.8",
"Close":"Tutup",
"Anomalies on the meteor":"Anomali di meteor",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ di sudut membuka menu jeda: Teruskan, Mula semula, Latihan, Grafik, Tetapan, Menu utama (dengan pengesahan). Telefon: ☰ di kanan atas (tindakan pertempuran — jubin \"⚡ Tindakan\"); PC: butang \"☰ Menu\" di kanan atas atau Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafik sentiasa biasa secara lalai — Dendy hanya jika kamu pilih: suis \"Grafik: Biasa / Dendy (8-bit) / 16-bit\" ada terus dalam menu utama dan menu jeda. Jika permainan sangat tersangkut, petua dengan butang \"Hidupkan Dendy\" akan muncul.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon dan tablet: butang tindakan \"✋\" di kanan muncul hanya apabila ada sesuatu yang boleh dibuat berdekatan — \"Ambil\" (simpanan, peti), \"Naik\" (kenderaan, turel, meriam), \"Bina\", \"Turun\", \"Bolt\" pada anomali. Kamu juga boleh ketik objek yang diserlahkan.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategi: tahan jari ~0.3 s (telefon bergetar, cincin kuning muncul) dan seret — kotak pilihan; leret biasa menggerakkan kamera. Ada juga butang \"Kotak\" di kanan; dalam latihan, langkah \"Kotak\" turut menerima ketikan pada skuad.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: butang kecil lebih mudah ditekan, senarai sokongan 📡 lebih besar, panel strategi tidak lagi menutupi skrin jeda dan keputusan. v7.8 kekal dalam menu \"🕘 Versi permainan\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menu ☰ pada telefon dan PC, tiada Dendy automatik, butang \"✋\" pada skrin sentuh, pilihan kotak pada telefon",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Tersangkut? Cuba grafik Dendy — ia lebih ringan.",
"Turn on Dendy":"Hidupkan Dendy",
