"Commander — still in development":"Komander — masih dalam pembangunan",
"Pause: resume, restart, training, graphics, settings, main menu":"Jeda: teruskan, mula semula, latihan, grafik, tetapan, menu utama",
"Menu: pause, restart, training, graphics, settings":"Menu: jeda, mula semula, latihan, grafik, tetapan",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Tahan jari pada tanah ~0.3 s — telefon bergetar dan cincin kuning muncul — kemudian seret tanpa mengangkat jari: kotak akan muncul. Atau gunakan butang \"Kotak\" di kanan. Mengetik skuad sahaja pun boleh.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Untuk skrin penuh pada iPhone: \"Kongsi\" ⬆ → \"Tambah ke Skrin Utama\" — permainan dibuka tanpa bar Safari.",
"Open portal-meteor.pages.dev for that.":"Untuk itu, buka portal-meteor.pages.dev.",
