"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: 100+ lagu oleh EDMITRY terus dalam game — butang 📻 (PC: kekunci 5, [ ] — lagu). Muzik distrim atas permintaan dan tidak membebankan game; kelantangan dan mula automatik dalam Tetapan, serta pautan \"Dengar di Spotify\".",
