"Radio: start by itself in battle":"Radio: mula sendiri dalam pertempuran",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: siborg dengan katana. Dibuka di Berek melalui penyelidikan \"Protokol Bayang\" (memerlukan Kilang Mech). Teleport sendiri ke zon musuh, mencincang musuh (tiada darah — hanya percikan api), terjahan, shuriken, berduel dengan ninja musuh. Kawal dia — mod AUTO atau kawalan manual (butang tersendiri di telefon).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 lagu EDMITRY terus dalam game. Kekunci 5 (boleh diubah), di telefon — ☰ → Tetapan → Bunyi. Kelantangan dan \"mula sendiri dalam pertempuran\" ada dalam tetapan; muzik diperlahankan semasa letupan dan suara radio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Bahasa baharu: Uzbek dan Tajik — lengkap; Cina, Sepanyol, Portugis — separa. Pemilih bahasa baharu di menu bersebelahan \"Perlawanan baharu\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: \"sembunyi ikon\" 👁 menyusun butang yang tinggal dalam lajur kemas di tepi kanan; potret tidak lagi bertindih; iPhone — game tidak lagi bertembung dengan gerak isyarat Safari, dan \"Kongsi → Tambah ke Skrin Utama\" melancarkannya skrin penuh.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Daripada v7.8.1: menu sudut ☰ (jeda, mula semula, latihan, grafik), tiada Dendy automatik, butang tindakan ✋ di telefon. v7.8.1 dan v7.8 kekal dalam menu \"🕘 Versi game\".",
