"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Pilih unit → \"▶ Kawal\" atau ketik dua kali. Butang mod di kanan atas: Ahli Strategi → Komander → Penembak.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Pilih unit → \"▶ Kawal\" atau klik dua kali. {0} berkitar: Ahli Strategi → Komander → Penembak.",
