"Living world: requests, hero quests, breakthrough ops":"Dunia hidup: permintaan, misi hero, operasi titik balik",
"Living world":"Dunia hidup",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Unit anda meminta bantuan dan memberi ganjaran, hero memberi misi, barisan hadapan yang terhenti dipecahkan dengan operasi",
"A request":"Permintaan",
"Breakthrough":"Titik balik",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Unit anda kadangkala meminta bantuan: panggilan radio, kad PERMINTAAN dan penanda ✋. Skuad terkepung — musnahkan musuh berdekatan. Ganjaran: askar melalui pod dari pangkalan, senjata dari bagasi buggy, tempat penembak atau perlindungan orbit. Tak mahu — ✕ atau abaikan sahaja.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Peninjau veteran \"Burung Hantu\" menawarkan misi. Y — terima (N — tolak). Pergi ke penanda ★, hapuskan pengawal dan berdiri di sebelah juruterbang selama 3 s — dia menyertai skuad anda.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Barisan hadapan terhenti — Ibu Pejabat menawarkan titik balik. Y — terima. Kuasai geganti selama 8 s tanpa musuh berdekatan: peta musuh kelihatan 60 s. Penjana — menara meriam musuh senyap 2 min. Dalam Ahli Strategi — \"Beri kepada skuad\". Musuh pun boleh berbuat begitu: awasi ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Unit anda meminta bantuan: kad PERMINTAAN dan penanda ✋. Musnahkan musuh berhampiran skuad yang terkepung — dapatkan ganjaran. ✕ — langkau.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Hero \"Burung Hantu\" menawarkan misi — ketik \"Terima\". Pergi ke ★, hapuskan pengawal, berdiri di sebelah juruterbang.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Barisan hadapan terhenti — ketik \"Terima\" dan kuasai geganti selama 8 s: peta musuh terbuka selama seminit.",
"Pod redeploy from the base: {0} m — through the sky portal":"Pemindahan melalui pod dari pangkalan: {0} m — menerusi portal langit",
"Pod away from the base! Hold on — exit over the target.":"Pod bertolak dari pangkalan! Berpeganglah — keluar di atas sasaran.",
"Landed at the objective!":"Mendarat di objektif!",
"LAUNCH FROM BASE":"PELANCARAN DARI PANGKALAN",
"LANDING":"PENDARATAN",
"REDEPLOY":"PEMINDAHAN",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Pelusa/«Bulu Keluli» — единый термин: \"Bulu Keluli\" ок",
"An engineer brushed the fluff off":"Jurutera membersihkan bulu itu",
"The fluff fell off — armour is safe":"Bulu itu gugur — perisai selamat",
