"Members: ":"Anggota: ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Kereta kebal tempur utama: meriam dan senapang mesin. \"Bulldog\" Konsortium lebih kebal, \"Labah-labah\" Kumpulan lebih laju.",
"Heavy tank":"Kereta kebal berat",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Penembak terbang autonomi: laju, rapuh, takut meriam antipesawat.",
"Upgrade":"Naik taraf",
"Longer, faster jetpacks for all infantry.":"Jetpack lebih jauh dan lebih laju untuk semua infantri.",
"Extractors mine more ore.":"Pengekstrak melombong lebih banyak bijih.",
"Army-wide levels: less damage taken / more damage dealt.":"Tahap seluruh tentera: kurang kerosakan diterima / lebih kerosakan dikenakan.",
"Levels":"Tahap",
"Base":"Pangkalan",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Jantung pangkalan: skuad, jurutera, pod, penyelidikan. Kalau Ibu Pejabat hilang, kamu kalah.",
"Produces: ":"Menghasilkan: ",
"Launch pad":"Pad pelancaran",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silo di sebelah Ibu Pejabat: pod, peti bekalan dan pengebom dilancarkan dari sini melalui portal langit. Tidak boleh membina di atasnya.",
"Economy":"Ekonomi",
"Key building":"Utama",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Titik lemah — bahagian belakang (enjin): kerosakan ×{0}. Meriam, 2 menara senapang mesin, pod roket; berpusing sangat perlahan — serang dari tepi.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Titik lemah — teras bercahaya di bawah perut: kerosakan dari bawah ×{0}. Pancaran herotan dan hentakan kawasan; melangkah melepasi penghadang — jaga jarak, jangan berkumpul.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Lawan: bom dan artileri (×{0}), roket (×{1}), pengeboman permaidani; peluru hampir tidak berkesan (×{2}).",
"Faction":"Puak",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Mesin laju, kawanan dron, terowong dan penjanaan semula. Infantri lebih ringan tetapi lebih laju; meriam dan rel lebih kuat.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Infantri berat berperisai kuasa, penghadang konkrit, pembaikan dan artileri. Lebih perlahan tetapi lebih kebal.",
